/** 品牌模型 Logo（矢量来源 LobeHub icons MIT + simple-icons CC0，共 44 家） */
object ModelLogos {

    private fun logo(name: String, pathData: String, tint: Long) =
        logoMulti(name, listOf(pathData to tint))

    private fun logoMulti(name: String, paths: List<Pair<String, Any?>>): ImageVector =
        androidx.compose.ui.graphics.vector.ImageVector.Builder(
            name = name, defaultWidth = 24.dp, defaultHeight = 24.dp,
            viewportWidth = 24f, viewportHeight = 24f,
        ).apply {
            paths.forEach { (d, fillRaw) ->
                val tint = when (fillRaw) {
                    is Number -> Color(fillRaw.toLong())
                    else -> Color((fillRaw as? Long) ?: 0xFF000000)
                }
                addPath(addPathNodes(d), fill = androidx.compose.ui.graphics.SolidColor(tint))
            }
        }.build()

