    private fun String.hasWord(w: String): Boolean =
        Regex("(?i)(^|[^a-z])" + Regex.escape(w) + "([^a-z]|${'$'})").containsMatchIn(this)

    fun forModel(model: String): ImageVector = when {
        model.hasWord("gpt") || model.hasWord("openai") || Regex("(?i)\bo[1345]\b").containsMatchIn(model) -> openaiLogo
        model.hasWord("claude") || model.hasWord("anthropic") -> anthropicLogo
        model.hasWord("deepseek") -> deepseekLogo
        model.hasWord("gemini") -> geminiLogo
        model.hasWord("gemma") -> gemmaLogo
        model.hasWord("glm") || model.hasWord("zhipu") || model.hasWord("chatglm") -> zhipuLogo
        model.hasWord("step") -> stepfunLogo
        model.hasWord("minimax") || model.hasWord("abab") -> minimaxLogo
        model.hasWord("kimi") || model.hasWord("moonshot") -> kimiLogo
        model.hasWord("qwen") || model.hasWord("qwq") || model.hasWord("qvq") -> qwenLogo
        model.hasWord("grok") -> grokLogo
        model.hasWord("xai") -> xaiLogo
        model.hasWord("nvidia") || model.hasWord("nemotron") || model.hasWord("nim") -> nvidiaLogo
        model.hasWord("ollama") -> ollamaLogo
        model.hasWord("openrouter") -> openrouterLogo
        model.hasWord("huggingface") || model.hasWord("hf") -> huggingfaceLogo
        model.hasWord("mistral") || model.hasWord("mixtral") -> mistralLogo
        model.hasWord("doubao") || model.contains("豆包") -> doubaoLogo
        model.hasWord("baichuan") -> baichuanLogo
        model.hasWord("agnes") -> agnesLogo
        model.hasWord("perplexity") -> perplexityLogo
        model.hasWord("cohere") || model.hasWord("command") -> cohereLogo
        model.hasWord("yi") || model.hasWord("01ai") -> yiLogo
        model.hasWord("hunyuan") -> hunyuanLogo
        model.hasWord("spark") || model.hasWord("星火") -> sparkLogo
        model.hasWord("ernie") || model.hasWord("wenxin") || model.hasWord("文心") -> ernieLogo
        model.hasWord("copilot") -> copilotLogo
        model.hasWord("bing") -> bingLogo
        model.hasWord("groq") -> groqLogo
        model.hasWord("together") -> togetherLogo
        model.hasWord("fireworks") -> fireworksLogo
        model.hasWord("reka") -> rekaLogo
        model.hasWord("lepton") -> leptonLogo
        model.hasWord("midjourney") || model.hasWord("mj") -> midjourneyLogo
        model.hasWord("suno") -> sunoLogo
        model.hasWord("kling") || model.hasWord("可灵") -> klingLogo
        model.hasWord("luma") -> lumaLogo
        model.hasWord("microsoft") || model.hasWord("phi") || model.hasWord("wizardlm") -> microsoftLogo
        model.hasWord("akasha") -> akashaLogo
        model.hasWord("fastgpt") -> fastgptLogo
        model.hasWord("metagpt") -> metagptLogo
        model.hasWord("llama") -> ollamaLogo
        else -> robotLogo
    }
}

/** 模型 Logo 组件（LobeHub 品牌彩色矢量） */
@Composable
fun ModelLogo(model: String, size: androidx.compose.ui.unit.Dp = 28.dp) {
    Box(
        Modifier.size(size).background(MaterialTheme.colorScheme.surfaceContainerHigh, CircleShape),
        contentAlignment = Alignment.Center,
    ) {
        Icon(ModelLogos.forModel(model), model, Modifier.size(size * 0.62f), tint = androidx.compose.ui.graphics.Color.Unspecified)
    }
}
